@startuml

class Hospital {}

class Office {}

class User {}

class Doctor extends User {}

class Patient extends User {}

class Schedule {}

class AppointmentType {
  + Name : string
  + Duration : int
}

class Appointment {
  + Date : date
  + StartTime : time
  + EndTime : time
}

Hospital "1" -- "*" Office
Office "1" -- "*" Schedule
Doctor "1" -- "*" Schedule : creates
Doctor "1" -- "*" Appointment : has
Patient "1" -- "*" Appointment : books
Schedule "1" -- "*" Appointment : contains
Appointment "*" -- "1" AppointmentType

AppointmentType "1" -- "0..1" AppointmentType : Blood Test
AppointmentType "1" -- "0..1" AppointmentType : Consultation
AppointmentType "1" -- "0..1" AppointmentType : Surgery

@enduml

